def transform(grid):
    h, w = len(grid), len(grid[0])
    axis = max(range(h), key=lambda r: sum(v == 6 for v in grid[r]))

    bars = []
    c = 0
    while c < w:
        color = grid[axis][c]
        if color in (6, 8):
            c += 1
            continue

        start = c
        while c + 1 < w and grid[axis][c + 1] == color:
            c += 1
        end = c

        up = down = 0
        for x in range(start, end + 1):
            n = 0
            r = axis - 1
            while r >= 0 and grid[r][x] == color:
                n += 1
                r -= 1
            up = max(up, n)

            n = 0
            r = axis + 1
            while r < h and grid[r][x] == color:
                n += 1
                r += 1
            down = max(down, n)

        bars.append((start, end, color, up, down))
        c += 1

    out = [row[:] for row in grid]

    # Remove original bar extensions while keeping the horizontal line.
    for start, end, color, _, _ in bars:
        for x in range(start, end + 1):
            for r in range(h):
                if r != axis and grid[r][x] == color:
                    out[r][x] = 8

    # Redistribute the bar heights in increasing order from left to right.
    profiles = sorted(
        ((up + down, up, down) for _, _, _, up, down in bars),
        key=lambda p: p[0]
    )
    for (start, end, color, _, _), (_, up, down) in zip(bars, profiles):
        for x in range(start, end + 1):
            for r in range(max(0, axis - up), min(h, axis + down + 1)):
                out[r][x] = color

    return out
